import{_ as t,o as l,c as n,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"All things in Moderation | Ceph Days London 2024","description":"","frontmatter":{"title":"All things in Moderation | Ceph Days London 2024","date":"2024-08-23T00:00:00.000Z","updated":"2024-08-24T00:00:00.000Z","tags":["Ceph","QoS技术","SEF对象存储","分布式存储","质量服务"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/All_things_in_Moderation_Ceph_Days_London_2024.md","filePath":"posts/2024/All_things_in_Moderation_Ceph_Days_London_2024.md","lastUpdated":1780459816000}'),s={name:"posts/2024/All_things_in_Moderation_Ceph_Days_London_2024.md"};function r(e,o,g,p,_,a){return l(),n("div",null,[...o[0]||(o[0]=[i("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： [请填写会议时间] <strong>会议地点</strong>： [请填写会议地点] <strong>参会人员</strong>： Jack（Bloomberg存储工程团队） <strong>会议主题</strong>： 在SEF对象存储上应用集群级服务质量（QoS）技术的经验分享</p><p><strong>会议内容</strong>：</p><p><strong>1. 背景</strong></p><ul><li>Bloomberg拥有大量SEF存储集群，涵盖生产、开发、测试和遗留环境。</li><li>由于处理请求和数据传输量巨大，团队开发了软件定义的QoS堆栈以优化性能和用户体验。</li></ul><p><strong>2. 自定义QoS解决方案</strong></p><ul><li>自行开发的QoS堆栈旨在： <ul><li>提供一致的性能体验。</li><li>维护集群性能标准。</li><li>为每个用户提供可配置的速率限制。</li><li>支持多站点集群。</li></ul></li></ul><p><strong>3. QoS架构</strong></p><ul><li>架构包括用户、SEF集群、Haproxy代理、定制CIS日志服务器、Redis实例和策略生成器。</li></ul><p><strong>4. 遇到的问题及解决方案</strong></p><ul><li><strong>传输限制执行</strong>： 改进为主动式，根据超出限制的程度调整暂停时间。</li><li><strong>并发传输</strong>： 限制客户端打开的连接数量，防止资源耗尽。</li><li><strong>昂贵请求</strong>： 需要更深入地分析请求，例如根据服务时间或请求复杂性进行限制。</li></ul><p><strong>5. 未来计划</strong></p><ul><li>进一步改进传输限制执行和并发传输问题。</li><li>研究更智能的请求分析方法，以处理昂贵请求。</li><li>考虑开源自定义QoS解决方案。</li></ul><p><strong>6. 总结</strong></p><ul><li>自定义QoS解决方案在Bloomberg的SEF存储集群中取得了成功。</li><li>通过不断改进和优化，该解决方案有助于提高性能和用户体验。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Jack将分享更多关于QoS架构和实施细节的信息。</li><li>团队将继续研究改进QoS解决方案的方法。</li><li>考虑开源自定义QoS解决方案。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到的关键计算机科学/CEPH领域英文原文关键词包括：SEF object storage, cluster wide quality of service, Haproxy, Reddis, rate limiting, connection limiting, expensive requests。</li></ul>",19)])])}const S=t(s,[["render",r]]);export{u as __pageData,S as default};
